#include <iostream>
#include <vector>
using namespace std;
struct Node { int v; Node *l = nullptr, *r = nullptr; Node(int v) : v(v) {} };
Node* insert(Node* node, int v) {
    if (!node) return new Node(v);
    if (v < node->v) node->l = insert(node->l, v);
    else node->r = insert(node->r, v);
    return node;
}
void preorder(Node* root, vector<int>& res) { if (!root) return; res.push_back(root->v); preorder(root->l, res); preorder(root->r, res); }
void inorder(Node* root, vector<int>& res) { if (!root) return; inorder(root->l, res); res.push_back(root->v); inorder(root->r, res); }
void postorder(Node* root, vector<int>& res) { if (!root) return; postorder(root->l, res); postorder(root->r, res); res.push_back(root->v); }
void print_v(const string& label, const vector<int>& v) {
    cout << label << ": ";
    for (size_t i = 0; i < v.size(); i++) { if (i > 0) cout << " "; cout << v[i]; }
    cout << "\n";
}
int main() {
    int n; if (cin >> n) {
        Node* root = nullptr;
        for (int i = 0; i < n; i++) {
            int v; cin >> v;
            root = insert(root, v);
        }
        vector<int> ino, pre, post;
        inorder(root, ino); preorder(root, pre); postorder(root, post);
        print_v("Inorder", ino); print_v("Preorder", pre); print_v("Postorder", post);
    }
    return 0;
}

