const fs = require("fs");
function main() {
    const toks = fs.readFileSync(0, "utf-8").trim().split(/\s+/).map(Number);
    if (toks.length > 0) {
        const n = toks[0], vals = toks.slice(1, 1 + n);
        class Node { constructor(v) { this.v = v; this.l = null; this.r = null; } }
        let root = null;
        function insert(node, v) {
            if (!node) return new Node(v);
            if (v < node.v) node.l = insert(node.l, v);
            else node.r = insert(node.r, v);
            return node;
        }
        for (const v of vals) root = insert(root, v);
        const ino = [], pre = [], post = [];
        function dfs(node) {
            if (!node) return;
            pre.push(node.v); dfs(node.l);
            ino.push(node.v); dfs(node.r);
            post.push(node.v);
        }
        dfs(root);
        console.log(`Inorder: ${ino.join(" ")}\nPreorder: ${pre.join(" ")}\nPostorder: ${post.join(" ")}`);
    }
}
main();

